(async()=>{document.body.classList.add('workspace-mode');document.querySelector('#home')?.remove();await Vibe.require();const bar=document.createElement('div');bar.className='platform-links';bar.innerHTML='<strong>Project Studio</strong><a href="/">Website</a><a href="/account/">Workbench</a><a href="/practice/">Practice</a>';document.body.prepend(bar);if(!location.hash.startsWith('#/'))location.hash='/dashboard';const s=document.createElement('script');s.src='/runtime/workspace.js';document.body.append(s);})();